def run_mapping(ctx: SparkContext, metrics: MappingMetrics = None) -> bool:
    """
    Execute the M_DDS_APL_FACT_GMS_DLY_MSD_INCDT mapping transformations.
    
    Args:
        ctx: SparkContext containing spark session and registered DataFrames
        metrics: Optional metrics tracker for logging
    
    Returns:
        bool: True if successful, False otherwise
    """
    spark = ctx.spark
    
    if metrics:
        metrics.start()
    
    try:
        # Reading Data From Source - read_DPA_FACT_GMS_DLY_MSD_INCDT
        df_src_1 = spark.read.format("jdbc").options(url=jdbc_url_source, driver="com.microsoft.sqlserver.jdbc.SQLServerDriver", dbtable="DPA_FACT_GMS_DLY_MSD_INCDT").load()
        # Normalize column names to lowercase for case-insensitive matching
        df_src_1 = normalize_column_names(df_src_1)
        print("Source Data Count df_src_1:", df_src_1.count())
        df_src_1 = df_src_1.coalesce(1).withColumn("jkey", monotonically_increasing_id())
        
        # Source Qualifier: apply_SQ_DPA_FACT_GMS_DLY_MSD_INCDT
        df_sq_2 = df_src_1
        # Select only SQ output ports (matches Informatica behavior)
        df_sq_2 = df_sq_2.select("MSD_INCDT_DATE_DMNS_KEY", "MSD_CRE_DATE_DMNS_KEY", "EST_SCD_KEY", "OFCR_TYPE_DMNS_KEY", "HSHLD_SIZE_DMNS_KEY", "MSD_CODE_SCD_KEY", "OFNDR_GNDR_DMNS_KEY", "OFNDR_AGE_GRP_DMNS_KEY", "OFNC_SCORE_GRP_DMNS_KEY", "AFT_CMLT_WRT_WARN_CASE_CNT", "CMLT_PNT_ALLT_CASE_CNT", "CMLT_MSD_TOT_CASE_CNT", "REC_RLS_IND", "LAST_REC_TXN_DATE", "LAST_REC_TXN_TYPE_CODE")
        ctx.register_df("df_sq_2", df_sq_2)
        
        # Update Strategy: apply_UPDTRANS
        # Strategy: DD_INSERT
        df_upd_3 = df_sq_2.withColumn("_update_strategy", lit("INSERT"))
        ctx.register_df("df_upd_3", df_upd_3)
        
        # Dropping control columns before write: _update_flag, _update_strategy, del_ins_upd_flag, del_upd_ins_flag, ins_upd_del_flag, DEL_INS_UPD_FLAG, DEL_UPD_INS_FLAG, INS_UPD_DEL_FLAG
        # Selecting only target-mapped columns with correct casing and data types
        # Write to Target: write_DDS_FACT_GMS_DLY_MSD_INCDT
        df_write = df_upd_3
        # Cast columns to match target schema data types
        if "rec_rls_ind" in [c.lower() for c in df_write.columns]:
            for c in df_write.columns:
                if c.lower() == "rec_rls_ind":
                    df_write = df_write.withColumn(c, col(c).cast(StringType()))
        if "last_rec_txn_date" in [c.lower() for c in df_write.columns]:
            for c in df_write.columns:
                if c.lower() == "last_rec_txn_date":
                    df_write = df_write.withColumn(c, col(c).cast(DateType()))
        if "last_rec_txn_type_code" in [c.lower() for c in df_write.columns]:
            for c in df_write.columns:
                if c.lower() == "last_rec_txn_type_code":
                    df_write = df_write.withColumn(c, col(c).cast(StringType()))
        # Drop identity columns (MSSQL will generate them)
        identity_cols_to_drop = ['src_rowid', 'SRC_ROWID']
        for col_to_drop in identity_cols_to_drop:
            if col_to_drop in df_write.columns:
                df_write = df_write.drop(col_to_drop)
            if col_to_drop.lower() in [c.lower() for c in df_write.columns]:
                for c in df_write.columns:
                    if c.lower() == col_to_drop.lower():
                        df_write = df_write.drop(c)
        # Drop control columns not in target definition
        for col_to_drop in ['_update_flag', '_update_strategy', 'del_ins_upd_flag', 'del_upd_ins_flag', 'ins_upd_del_flag', 'DEL_INS_UPD_FLAG', 'DEL_UPD_INS_FLAG', 'INS_UPD_DEL_FLAG']:
            if col_to_drop in df_write.columns:
                df_write = df_write.drop(col_to_drop)
        # Select columns with exact casing from target definition
        target_col_map = {c.lower(): c for c in ['MSD_INCDT_DATE_DMNS_KEY', 'MSD_CRE_DATE_DMNS_KEY', 'EST_SCD_KEY', 'OFCR_TYPE_DMNS_KEY', 'HSHLD_SIZE_DMNS_KEY', 'MSD_CODE_SCD_KEY', 'OFNDR_GNDR_DMNS_KEY', 'OFNDR_AGE_GRP_DMNS_KEY', 'OFNC_SCORE_GRP_DMNS_KEY', 'AFT_CMLT_WRT_WARN_CASE_CNT', 'CMLT_PNT_ALLT_CASE_CNT', 'CMLT_MSD_TOT_CASE_CNT', 'REC_RLS_IND', 'LAST_REC_TXN_DATE', 'LAST_REC_TXN_TYPE_CODE']}
        final_cols = []
        for c in df_write.columns:
            if c.lower() in target_col_map:
                if c != target_col_map[c.lower()]:
                    df_write = df_write.withColumnRenamed(c, target_col_map[c.lower()])
                final_cols.append(target_col_map[c.lower()])
        df_write = df_write.select(*[col for col in ['MSD_INCDT_DATE_DMNS_KEY', 'MSD_CRE_DATE_DMNS_KEY', 'EST_SCD_KEY', 'OFCR_TYPE_DMNS_KEY', 'HSHLD_SIZE_DMNS_KEY', 'MSD_CODE_SCD_KEY', 'OFNDR_GNDR_DMNS_KEY', 'OFNDR_AGE_GRP_DMNS_KEY', 'OFNC_SCORE_GRP_DMNS_KEY', 'AFT_CMLT_WRT_WARN_CASE_CNT', 'CMLT_PNT_ALLT_CASE_CNT', 'CMLT_MSD_TOT_CASE_CNT', 'REC_RLS_IND', 'LAST_REC_TXN_DATE', 'LAST_REC_TXN_TYPE_CODE'] if col in df_write.columns])
        df_write.write.format("delta").mode("append").saveAsTable("DDS_FACT_GMS_DLY_MSD_INCDT")
        if metrics:
            metrics.log_row_count("write_DDS_FACT_GMS_DLY_MSD_INCDT_written", df_write.count())
        
        
        if metrics:
            metrics.complete()
        
        return True
        
    except Exception as e:
        if metrics:
            metrics.fail(e)
        raise


